"""Node management markup and script, using the shared admin panel components."""

MARKUP = r'''
<section id="nodes" hidden aria-label="节点管理">
<div id="nodeDisabled" class="panel"><div class="panel-body"><h2>先启用远程下载服务</h2><p>在主控配置 DISTRIBUTED_ENABLED=true，使用 compose.distributed.yaml 启动，并为 Agent API 配置 HTTPS 反向代理，同时转发 /v1/agent/ 和 /install/。启用后刷新本页。</p></div></div>
<div id="nodeControls" hidden>
<div class="panel"><div class="panel-head"><div><h2>连接主控</h2><p>填写附属 VPS 可以访问的 Agent API 地址，通常与管理网页使用不同域名。</p></div><span class="tag">HTTPS</span></div><div class="panel-body"><form id="nodeOriginForm" class="search-form"><label for="nodeOrigin">Agent 地址</label><input id="nodeOrigin" type="url" maxlength="300" placeholder="https://agents.example.com" required><button class="primary">保存地址</button></form><p class="muted">只填写源地址，不带路径。更改地址会使未使用的安装命令失效；已安装节点需重新生成命令并安装。</p></div></div>
<div class="panel"><div class="panel-head"><div><h2 id="nodeFormTitle">添加下载节点</h2><p>每台 VPS 同时处理一本漫画；图片并发仅影响这一本内部的下载。</p></div><span class="tag">最多 32 个节点</span></div><div class="panel-body"><form id="nodeForm"><div class="node-fields"><label>节点 ID<input id="nodeId" pattern="[A-Za-z0-9_\-]{1,48}" maxlength="48" placeholder="vps-1" required></label><label>显示名称<input id="nodeLabel" maxlength="64" placeholder="香港节点" required></label><label>图片并发组数<input id="nodeConcurrency" type="number" min="1" max="16" step="1" value="2" required></label></div><div class="button-row"><button id="nodeSubmit" class="primary">创建并生成安装命令</button><button id="nodeCancelEdit" type="button" class="quiet" hidden>取消编辑</button></div></form></div></div>
<div id="nodeInstall" class="panel" hidden><div class="panel-head"><div><h2>一键安装命令</h2><p id="nodeExpiry" role="status"></p></div><button id="nodeCopy" class="primary">复制命令</button></div><div class="panel-body"><label for="nodeCommand" class="field-label">在目标 Linux VPS 以 root 身份执行</label><textarea id="nodeCommand" rows="5" readonly spellcheck="false"></textarea><p class="muted">凭据 30 分钟内仅可使用一次，请勿分享。自动配置 Agent，无需克隆仓库或编辑环境文件。重新安装会更新节点密钥并回收当前任务；安装失败请重新生成命令。</p></div></div>
</div>
<div class="panel"><div class="panel-head"><div><h2>下载节点</h2><p id="agentSummary">正在加载节点状态</p></div><span class="tag">VPS Agent</span></div><div id="agentTable" class="scroll" tabindex="0" role="region" aria-label="下载节点列表"></div></div>
</section>
'''

SCRIPT = r'''
let nodeRequest=0,nodeSession=0,nodeBusy=false;
function clearInstall(){el('nodeInstall').hidden=true;el('nodeCommand').value='';el('nodeExpiry').textContent='';}
function resetNodeForm(){el('nodeForm').reset();el('nodeId').readOnly=false;el('nodeCancelEdit').hidden=true;el('nodeFormTitle').textContent='添加下载节点';el('nodeSubmit').textContent='创建并生成安装命令';}
function clearNodes(){nodeSession++;nodeRequest++;clearInstall();resetNodeForm();el('nodeOrigin').value='';el('nodeControls').hidden=true;empty('agentTable');}
function showInstall(d){el('nodeCommand').value=d.command;el('nodeExpiry').textContent='节点 '+d.node_id+' · 有效至 '+new Date(d.expires_at*1000).toLocaleString();el('nodeInstall').hidden=false;el('nodeCommand').focus();}
async function mutateNode(data){if(nodeBusy)return;nodeBusy=true;const session=nodeSession;el('nodeSubmit').disabled=true;try{const d=await api('nodes',data);if(session!==nodeSession||adminId===null)return;clearInstall();if(d.command)showInstall(d);if(['create','update','delete'].includes(data.action))resetNodeForm();await loadNodes();if(session!==nodeSession||adminId===null)return;el('notice').dataset.tone='success';el('notice').textContent=d.command?'安装命令已生成，请复制到目标 VPS 执行':'节点设置已保存';}finally{nodeBusy=false;el('nodeSubmit').disabled=false;}}
function nodeButton(label,handler,danger=false){const b=document.createElement('button');b.className='small '+(danger?'danger':'quiet');b.textContent=label;b.onclick=()=>safe(async()=>{if(nodeBusy)return;b.disabled=true;try{await handler();}finally{b.disabled=false;}});return b;}
function nodeActions(a){const group=document.createElement('div');group.className='node-actions';group.append(nodeButton('编辑',async()=>{el('nodeId').value=a.id;el('nodeId').readOnly=true;el('nodeLabel').value=a.label;el('nodeConcurrency').value=a.concurrency;el('nodeFormTitle').textContent='编辑节点 '+a.id;el('nodeSubmit').textContent='保存节点';el('nodeCancelEdit').hidden=false;el('nodeLabel').focus();}),nodeButton('安装命令',async()=>{if(a.registered&&!confirm('生成节点 '+a.id+' 的重新安装命令？执行命令时将更新密钥并回收该节点当前任务。'))return;await mutateNode({action:'install',id:a.id});}),nodeButton(a.enabled?'停用':'启用',async()=>{if(a.enabled&&!confirm('停用节点 '+a.id+'？正在执行的任务将按重试规则回到队列。'))return;await mutateNode({action:'enabled',id:a.id,enabled:!a.enabled});},!!a.enabled),nodeButton('删除',async()=>{if(confirm('删除节点 '+a.id+'？旧 Agent 将无法连接；目标 VPS 上的容器需自行停止。'))await mutateNode({action:'delete',id:a.id});},true));return group;}
async function loadNodes(){const request=++nodeRequest,session=nodeSession;try{const d=await api('nodes');if(request!==nodeRequest||session!==nodeSession||adminId===null)return;el('nodeDisabled').hidden=d.enabled;el('nodeControls').hidden=!d.enabled;if(document.activeElement!==el('nodeOrigin'))el('nodeOrigin').value=d.public_url||'';el('agentSummary').textContent=d.enabled?'每台 VPS 同时下载一本漫画 · '+d.agents.filter(a=>a.online).length+' / '+d.agents.length+' 在线':'本机下载模式';if(!d.agents.length){empty('agentTable',d.enabled?'尚未添加节点':'尚未启用远程下载',d.enabled?'保存 Agent 地址后，创建第一个节点并复制安装命令。':'完成主控配置后刷新本页。');}else table('agentTable',['节点','状态','图片并发','当前漫画 / 章节进度','最近通信','操作'],d.agents.map(a=>[stack(a.label,a.id),badge(!a.enabled?'已停用':a.online?'在线':a.registered?'离线':'待安装',!a.enabled?'muted':a.online?'success':'warn'),a.concurrency+' 组',a.task?stack(a.task.title,'JM'+a.task.source_id+' · '+a.received_pages+' / '+a.total_pages+' 页'):'空闲',a.last_seen_seconds===null?'—':a.last_seen_seconds+' 秒前',nodeActions(a)]));stamp();}catch(e){if(request!==nodeRequest||session!==nodeSession)return;empty('agentTable','节点加载失败','请刷新重试。');throw e;}}
el('nodeOriginForm').onsubmit=e=>{e.preventDefault();safe(()=>mutateNode({action:'origin',public_url:el('nodeOrigin').value.trim()}));};
el('nodeForm').onsubmit=e=>{e.preventDefault();safe(()=>mutateNode({action:el('nodeId').readOnly?'update':'create',id:el('nodeId').value.trim(),label:el('nodeLabel').value.trim(),concurrency:Number(el('nodeConcurrency').value)}));};
el('nodeCancelEdit').onclick=resetNodeForm;
el('nodeCopy').onclick=()=>safe(async()=>{if(!el('nodeCommand').value)return;try{await navigator.clipboard.writeText(el('nodeCommand').value);el('notice').dataset.tone='success';el('notice').textContent='安装命令已复制';}catch(e){el('nodeCommand').focus();el('nodeCommand').select();throw Error('浏览器未允许自动复制，已选中命令，请手动复制。');}});
'''
